const body = $input.first().json.body || {};
const value = (((body.entry || [])[0] || {}).changes || [])[0]?.value || {};
const msg = (value.messages || [])[0];
if (!msg) return [];                        // status updates (sent/delivered/read) -> ignore
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || [];
if (sd.seen.includes(msg.id)) return [];    // Meta retry -> ignore duplicate
sd.seen.push(msg.id);
if (sd.seen.length > 200) sd.seen = sd.seen.slice(-100);
sd.busy = sd.busy || {};
if (sd.busy[String(msg.from)] && Date.now() - sd.busy[String(msg.from)] < 150000) return [];   // retry in progress -> ignore follow-ups
const text = msg.type === 'text' ? (msg.text?.body || '').trim() : '';
const norm = text.toLowerCase().replace(/\s+/g, ' ');
const isTrigger = 1;   // any message starts/keeps the session
// --- language detection (sticky for short replies like "yes" / "ok") ---
sd.lang = sd.lang || {};
const from = String(msg.from);
const HIN = /\b(hai|hain|hu|hoon|kya|kitna|kitne|kitni|chahiye|chahie|chahiyen|mujhe|mereko|muje|karo|karna|karni|kardo|krdo|krna|aap|aapka|aapki|apka|apki|nahi|nahin|nhi|haan|han|bhai|batao|bata|bataiye|ka|ki|ke|mera|mere|meri|kal|aaj|parso|hoga|rahega|rhega|bhi|abhi|lunga|lungi|dena|dijiye|wala|wali|mein|mai|hum|hame|humein|kab|kaha|kaise|kaun|kon|ek|teen|char|sirf|lekin|aur|ya|toh|kitne din|raat|din|paisa|rupaye|theek|thik|sahi|accha|achha|bilkul|zaroor|jaldi|dobara|phir|isme|usme|yeh|woh)\b/gi;
const ENG = /\b(the|i|we|want|book|booking|room|rooms|price|please|how|what|is|are|you|need|for|my|can|do|does|have|available|check|name|yes|no|hello|hi|hey|tell|me|cancel|status|from|till|tomorrow|today|night|nights|guests|guest|with|and|of|in|on|at|a|an)\b/gi;
let langCode = sd.lang[from] || 'eng';
if (/[ऀ-ॿ]/.test(text)) langCode = 'dev';
else if (text) {
  const h = (text.match(HIN) || []).length, e = (text.match(ENG) || []).length;
  if (h >= 1 && h >= e - 1 && /\b(hai|hain|kya|kitna|kitne|kitni|chahiye|chahie|mujhe|mereko|karo|karna|aap|aapka|nahi|nahin|nhi|haan|han|bhai|batao|bata|bataiye|mera|mere|meri|hoga|rahega|lunga|dijiye|kaise|kab|kaha|theek|thik|accha|achha|bilkul|zaroor)\b/i.test(text)) langCode = 'hin';
  else if (e >= 2 && h === 0) langCode = 'eng';
  else if (h === 0 && /^(hello|hi|hey|hii+|good (morning|evening|afternoon))\b/i.test(text)) langCode = 'eng';
  else if (e >= 3 && e > h * 2) langCode = 'eng';
}
sd.lang[from] = langCode;
const LN = { eng: ['ENGLISH', 'Reply fully in English. No Hindi words.', 'english'],
             hin: ['HINGLISH', 'Reply in Hindi written in Roman letters mixed with common English words (rooms, check-in, total). Example: "Aapko kaun si dates chahiye?"', 'hinglish'],
             dev: ['HINDI', 'Reply in Hindi in Devanagari script.', 'hindi'] }[langCode];
const agent_text = '[Reply language: ' + LN[0] + ' - ' + LN[1] + ' Use guest_language = ' + LN[2] + ' in tools.]\n' + text;
// --- candidate ID strings typed by the guest (stored only as SHA-256 hashes, see Session Update) ---
const words = text.toUpperCase().split(/\s+/).map(x => x.replace(/[^A-Z0-9]/g, '')).filter(Boolean);
const cand = new Set();
for (let i = 0; i < words.length; i++) { let s = ''; for (let l = 0; l < 4 && i + l < words.length; l++) { s += words[i + l]; if (s.length >= 6 && s.length <= 20) cand.add(s); } }
const whole = words.join(''); if (whole.length >= 6 && whole.length <= 20) cand.add(whole);
const idtok = Array.from(cand).slice(0, 40);
return [{ json: { from: msg.from, type: msg.type, text, agent_text, lang: langCode, idtok, id: msg.id, isTrigger } }];

