  '{{ String($fromAI('check_in', `Check-in date in YYYY-MM-DD`, 'string')).replace(/[^0-9-]/g,'') }}', '{{ String($fromAI('check_out', `Check-out date in YYYY-MM-DD (11 AM check-out day)`, 'string')).replace(/[^0-9-]/g,'') }}', {{ parseInt($fromAI('ac_rooms', `Number of AC rooms requested (0 if none)`, 'number')) || 0 }}, {{ parseInt($fromAI('nonac_rooms', `Number of Non-AC rooms requested (0 if none)`, 'number')) || 0 }}, {{ parseInt($fromAI('guests', `Total number of guests in the whole party`, 'number')) || 1 }}, '{{ (['hindi','hinglish'].includes(String($fromAI('guest_language', `Guest language detected from the conversation: english, hindi or hinglish. Never ask the guest.`, 'string')).toLowerCase().replace(/[^a-z]/g,'')) ? String($fromAI('guest_language', `Guest language detected from the conversation: english, hindi or hinglish. Never ask the guest.`, 'string')).toLowerCase().replace(/[^a-z]/g,'') : 'english') }}', {{ $fromAI('add_more_rooms', `true only if the guest explicitly asks to add rooms to an existing booking`, 'boolean') ? 1 : 0 }}, @bc, @br);
