const sd = $getWorkflowStaticData('global');
sd.tries = sd.tries || {};
sd.busy = sd.busy || {};
sd.lang = sd.lang || {};
const lang = sd.lang[from] || 'eng';
sd.tries[id] = (sd.tries[id] || 0) + 1;
sd.busy[from] = Date.now();
const keys = Object.keys(sd.tries);
if (keys.length > 100) for (const k of keys.slice(0, 50)) delete sd.tries[k];
const n = sd.tries[id];
const err = JSON.stringify($input.first().json).toLowerCase();
const limited = err.includes('rate limit') || err.includes('429') || err.includes('too many requests');
// how long Groq says to wait ("try again in 14.3s" / "1m2.5s" / "850ms") + 2 s safety, between 6 and 30 s
let wait = 15;
const mm = err.match(/try again in (?:(\d+)m)?([\d.]+)(ms|s)/);
if (mm) wait = (mm[1] ? Number(mm[1]) * 60 : 0) + (mm[3] === 'ms' ? Number(mm[2]) / 1000 : Number(mm[2]));
wait = Math.min(30, Math.max(6, Math.ceil(wait) + 2));
return [{ json: { n, retry: limited && n <= 4, first: n === 1, lang, wait } }];

