    },
    EXPIRED: {
      hindi: 'क्षमा करें, आपकी बुकिंग रिक्वेस्ट ' + b.booking_code + ' समय पर approve नहीं हो पाई, इसलिए कमरे छोड़ दिए गए हैं। दोबारा कोशिश करने के लिए हमें मैसेज करें।',
      hinglish: 'Sorry, aapki booking request ' + b.booking_code + ' time par approve nahi ho payi, isliye rooms release kar diye gaye. Dobara try karne ke liye humein message karein.',
      english: 'Sorry, your booking request ' + b.booking_code + ' was not approved in time, so the rooms were released. Please message us again to try once more.'
    }
  };
  const t = T[b.status]; if (!t) return '';
  return t[lang] || t.english;
}

if (!valid) return [{ json: { html: invalid, notify: false } }];
const final = b.status === 'CONFIRMED' || b.status === 'REJECTED';
const justNow = Number(b.decided_ago) <= 20;
const notify = final && Number(b.guest_notified) === 0;
let banner;
if (final && justNow) banner = '<div class="sub"><b>' + (b.status === 'CONFIRMED' ? '✅ Approved.' : '❌ Rejected.') + '</b> The guest is being notified on WhatsApp.</div>';
else if (b.status === 'EXPIRED') banner = '<div class="sub"><b>⏰ Expired.</b> The hold time is over and the rooms were released, so it can not be approved now.</div>';
else banner = '<div class="sub"><b>Already handled.</b> No change was made.' + (notify ? ' The guest message is being sent again.' : '') + '</div>';
const html = page('Booking ' + b.booking_code, head(b) + banner + details(b));
return [{ json: { html, notify, phone: b.phone, msg: notify ? buildMsg(b) : '', booking_code: b.booking_code } }];

const inr = n => 'Rs ' + Number(n || 0).toLocaleString('en-IN');

function buildMsg(b) {
  const lang = String(b.guest_language || 'english').trim().toLowerCase();
  const total = inr(b.total);
  const why = b.reject_reason ? b.reject_reason : '';
  const T = {
    CONFIRMED: {
      hindi: '✅ आपकी बुकिंग CONFIRMED हो गई है!\nबुकिंग कोड: ' + b.booking_code + '\nकमरे: ' + b.room_details + '\nचेक-इन: ' + b.ci + '\nचेक-आउट: ' + b.co + ', सुबह 11:00 बजे\nकुल राशि: ' + total + ' (भुगतान होटल में करें)\nकृपया अपना ओरिजिनल फोटो ID साथ लाएं।',
      hinglish: '✅ Aapki booking CONFIRMED ho gayi hai!\nBooking code: ' + b.booking_code + '\nRooms: ' + b.room_details + '\nCheck-in: ' + b.ci + '\nCheck-out: ' + b.co + ', 11:00 AM\nTotal: ' + total + ' (payment hotel par karein)\nPlease apna original photo ID saath laayein.',
      english: '✅ Your booking is CONFIRMED!\nBooking code: ' + b.booking_code + '\nRooms: ' + b.room_details + '\nCheck-in: ' + b.ci + '\nCheck-out: ' + b.co + ', 11:00 AM\nTotal: ' + total + ' (pay at hotel)\nPlease carry your original photo ID.'
    },
    REJECTED: {
      hindi: 'हमें खेद है, आपकी बुकिंग रिक्वेस्ट ' + b.booking_code + ' स्वीकार नहीं हो सकी।' + (why ? ' कारण: ' + why + '.' : '') + ' दूसरी तारीख या कमरे के विकल्प के लिए हमें मैसेज करें।',
      hinglish: 'Sorry, aapki booking request ' + b.booking_code + ' approve nahi ho saki.' + (why ? ' Reason: ' + why + '.' : '') + ' Dusri dates ya room type ke liye humein message karein.',
      english: 'Sorry, your booking request ' + b.booking_code + ' could not be approved.' + (why ? ' Reason: ' + why + '.' : '') + ' Please message us to try other dates or room types.'
    },
    EXPIRED: {
      hindi: 'क्षमा करें, आपकी बुकिंग रिक्वेस्ट ' + b.booking_code + ' समय पर approve नहीं हो पाई, इसलिए कमरे छोड़ दिए गए हैं। दोबारा कोशिश करने के लिए हमें मैसेज करें।',
      hinglish: 'Sorry, aapki booking request ' + b.booking_code + ' time par approve nahi ho payi, isliye rooms release kar diye gaye. Dobara try karne ke liye humein message karein.',
      english: 'Sorry, your booking request ' + b.booking_code + ' was not approved in time, so the rooms were released. Please message us again to try once more.'
    }
  };
  const t = T[b.status]; if (!t) return '';
  return t[lang] || t.english;
}

return $input.all().map(i => {
  const b = i.json;
  return { json: { booking_code: String(b.booking_code).replace(/[^A-Za-z0-9]/g, ''), phone: String(b.phone).replace(/\D/g, ''), msg: buildMsg(b) } };
}).filter(x => x.json.msg);

const out = String($('Hotel AI Agent').first().json.output ?? '').trim();
const lang = $('Clean Message').first().json.lang || 'eng';
const rows = $input.all().map(i => i.json).filter(r => r && r.booking_code);

// Does the reply CLAIM a booking is confirmed?
const CLAIM = /confirmed|confirm\s+ho\s+(gayi|gaya|chuki|chuka|gai)|confirm\s+hai|कन्फर्म|कंफर्म|पक्की\s+हो/i;
const NEG = /\b(not|isn't|isnt|n't|yet|pending|nahi|nahin|nhi|abhi tak|once|after|until|will be|will get|jab|baad|if)\b|नहीं|अभी तक|जब|बाद/i;
if (!out || !CLAIM.test(out) || NEG.test(out)) return [{ json: { output: out, guarded: false } }];

const codes = out.match(/HB[0-9A-F]{6}/g) || [];
let bad = null;
if (codes.length) {
  const known = rows.filter(r => codes.includes(r.booking_code));
  bad = known.find(r => r.status !== 'CONFIRMED') || (known.length ? null : (rows[0] || { booking_code: codes[0], status: 'NONE' }));
} else {
  bad = rows.length ? (rows[0].status !== 'CONFIRMED' ? rows[0] : null) : { booking_code: '', status: 'NONE' };
}
if (!bad) return [{ json: { output: out, guarded: false } }];   // the claim is true

const c = bad.booking_code, m = Number(bad.mins_left) || 0;
const T = {
  PENDING: {
    eng: `Your booking request ${c} is not confirmed yet. It is waiting for the receptionist's approval (about ${m} min left for approval). I will message you here as soon as it is decided.`,
    hin: `Aapki booking request ${c} abhi confirm nahi hui hai. Receptionist ke approval ka wait hai (approval ke liye lagbhag ${m} minute bache hain). Decision hote hi main yahin aapko message karunga.`,
    dev: `आपकी बुकिंग रिक्वेस्ट ${c} अभी कन्फर्म नहीं हुई है। रिसेप्शनिस्ट के अप्रूवल का इंतज़ार है (लगभग ${m} मिनट बचे हैं)। फैसला होते ही मैं यहीं आपको मैसेज करूँगा।`
  },
  EXPIRED: {
    eng: `Your booking request ${c} was not approved in time, so it is NOT confirmed and the rooms were released. Please tell me if you would like to send the request again.`,
    hin: `Aapki booking request ${c} time par approve nahi hui, isliye wo confirm NAHI hai aur rooms release ho gaye. Dobara request bhejni ho to bataiye.`,
    dev: `आपकी बुकिंग रिक्वेस्ट ${c} समय पर अप्रूव नहीं हुई, इसलिए वह कन्फर्म नहीं है और कमरे छोड़ दिए गए हैं। दोबारा रिक्वेस्ट भेजनी हो तो बताइए।`
  },
  REJECTED: {
    eng: `Your booking request ${c} was not approved, so it is not confirmed.${bad.reject_reason ? ' Reason: ' + bad.reject_reason + '.' : ''} I can help you with other dates or room types.`,
    hin: `Aapki booking request ${c} approve nahi hui, isliye confirm nahi hai.${bad.reject_reason ? ' Reason: ' + bad.reject_reason + '.' : ''} Dusri dates ya room type ke liye main help kar sakta hu.`,
    dev: `आपकी बुकिंग रिक्वेस्ट ${c} अप्रूव नहीं हुई, इसलिए कन्फर्म नहीं है। दूसरी तारीख या कमरे के लिए मैं मदद कर सकता हूँ।`
  },
  CANCELLED: {
    eng: `Booking ${c} was cancelled, so it is not confirmed. I can help you make a new booking if you like.`,
    hin: `Booking ${c} cancel ho chuki hai, isliye confirm nahi hai. Nayi booking karni ho to main help kar sakta hu.`,
    dev: `बुकिंग ${c} रद्द हो चुकी है, इसलिए कन्फर्म नहीं है। नई बुकिंग करनी हो तो मैं मदद कर सकता हूँ।`
  },
  NONE: {
    eng: `I could not find a booking for your number, so nothing is confirmed. Would you like to make a booking?`,
    hin: `Mujhe aapke number par koi booking nahi mili, isliye kuch confirm nahi hai. Kya aap booking karna chahenge?`,
    dev: `मुझे आपके नंबर पर कोई बुकिंग नहीं मिली, इसलिए कुछ कन्फर्म नहीं है। क्या आप बुकिंग करना चाहेंगे?`
  }
};
const set = T[bad.status] || T.NONE;
return [{ json: { output: set[lang] || set.eng, guarded: true, original: out } }];
